<?php $food=\App\Domain\FoodData::validate($snapshot['food_data']); $a=$food['allergens'];$n=$food['nutrition']; ?>
<section class="mt-4"><h3>Date pentru aplicațiile de consum</h3><dl class="preview-data"><dt>Alergeni</dt><dd><?php if($a['status']==='unknown'):?>Declarația alergenilor nu este completată<?php else:?>Declarație verificată de producător<?php if($a['contains']):?><br>Conține: <?=e(implode(', ',array_map(fn($k)=>\App\Domain\FoodData::ALLERGENS[$k],$a['contains'])))?><?php endif?><?php if($a['may_contain']):?><br>Posibile urme: <?=e(implode(', ',array_map(fn($k)=>\App\Domain\FoodData::ALLERGENS[$k],$a['may_contain'])))?><?php endif?><?php endif?></dd><dt>Nutriție</dt><dd><?php if($n['status']==='unknown'):?>Valorile nutriționale nu sunt completate<?php else:?><?=e(['per_100_g'=>'Per 100 g','per_100_ml'=>'Per 100 ml','per_portion'=>'Per porție'][$n['basis']])?> · <?=$n['preparation']==='as_prepared'?'Preparat':'Ca atare'?> · <?=e($n['jurisdiction'])?><?php foreach($n['values']as$key=>$number):?><br><?=e(['energy_kj'=>'Energie (kJ)','energy_kcal'=>'Energie (kcal)','fat_g'=>'Grăsimi (g)','saturates_g'=>'Saturați (g)','carbohydrate_g'=>'Carbohidrați (g)','sugars_g'=>'Zaharuri (g)','polyols_g'=>'Polioli (g)','fibre_g'=>'Fibre (g)','protein_g'=>'Proteine (g)','salt_g'=>'Sare (g)'][$key])?>: <?=e($number)?><?php endforeach?><?php if($n['portion']):?><br>Porție: <?=e($n['portion']['amount'])?> <?=e($n['portion']['unit'])?><?php endif?><?php endif?></dd><?php if($food['after_opening']):?><dt>După deschidere</dt><dd><?=e($food['after_opening']['hours'])?> ore · <?=e($food['after_opening']['conditions'])?></dd><?php endif?></dl></section>
